PROGRAM ST_S04_KVALITETSKONTROLL
VAR
    stegPsh1 : INT := 0;
    stegPsh2 : INT := 0;
    tmr1     : TON;
    tmr2     : TON;
    trigRdy  : R_TRIG;
    verdict  : INT := 0;
END_VAR

tmr1(IN := (stegPsh1 = 1), PT := T#400ms);
tmr2(IN := (stegPsh2 = 1), PT := T#400ms);
trigRdy(CLK := ST220_CAM_READY);

IF NOT EMG_OK OR NOT AIR_OK OR NOT ST220_PSH_HOME THEN
    ST220_CNV_RUN  := FALSE;
    ST220_PSH_RWK  := FALSE;
    ST220_PSH_SCR  := FALSE;
    ST220_CAM_TRIG := FALSE;
    stegPsh1 := 0;
    stegPsh2 := 0;
ELSE
    ST220_CNV_RUN := TRUE;
    ST220_CAM_TRIG := NOT ST220_CAM_READY;

    IF trigRdy.Q THEN
        verdict := ST220_CAM_VERDICT;
        IF verdict = 2 OR verdict < 1 OR verdict > 3 THEN
            ST220_PSH_RWK := TRUE;
            stegPsh1 := 1;
        ELSIF verdict = 3 THEN
            ST220_PSH_SCR := TRUE;
            stegPsh2 := 1;
        END_IF;
    END_IF;

    IF tmr1.Q THEN
        ST220_PSH_RWK := FALSE;
        stegPsh1 := 0;
    END_IF;
    IF tmr2.Q THEN
        ST220_PSH_SCR := FALSE;
        stegPsh2 := 0;
    END_IF;
END_IF;
END_PROGRAM

